下面是并发进程的程序代码，正确的是（ ）。
Semaphore x1=x2=y=1;
int c1=c2=0;
P1(){ while(1){ P(x1); if(++c1==1)P(y); V(x1); computer(A); P(x1); if(--c1==0)V(y); V(x1); } }
P2(){ while(1){ P(x2); if(++c2==1)P(y); V(x2); computer(B); P(x2); if(--c2==0)V(y); V(x2); } }

有两个并发进程，对于如下这段程序的运行，正确的说法是（ ）。
int x,y,z,t,u;
P1(){ while(1){ x=1; y=0; if x>=1 then y=y+1; z=y; } }
P2(){ while(1){ x=0; t=0; if x<=1 then t=t+2; u=t; } }

